<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; requireRole('admin'); $logs = $pdo->query('SELECT id, user_id, role_name, action, entity_type, entity_id, description, ip_address, created_at FROM audit_logs ORDER BY created_at DESC, id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Audit Logs'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">System oversight</p><h1 class="h2">Audit Logs</h1></div><span class="badge text-bg-dark">Admin only</span></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Time</th><th>Action</th><th>Role</th><th>Entity</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td><?= e($log['created_at']) ?></td><td><span class="badge text-bg-light"><?= e($log['action']) ?></span></td><td><?= e($log['role_name']) ?></td><td><?= e($log['entity_type']) ?> #<?= e((string) $log['entity_id']) ?></td><td><?= e($log['description']) ?></td><td><?= e($log['ip_address']) ?></td></tr><?php endforeach; ?><?php if (!$logs): ?><tr><td colspan="6" class="text-muted">No audit logs found.</td></tr><?php endif; ?></tbody></table></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>